def median_of_two_sorted(a, b):
    """Return the median of two sorted lists. Both lists cannot be empty."""
    if not a and not b:
        raise ValueError("At least one list must be non-empty")

    # Binary-search the shorter list.
    if len(a) > len(b):
        a, b = b, a

    m, n = len(a), len(b)
    half = (m + n + 1) // 2
    low, high = 0, m

    while low <= high:
        i = (low + high) // 2
        j = half - i

        if i < m and j > 0 and b[j - 1] > a[i]:
            low = i + 1
        elif i > 0 and j < n and a[i - 1] > b[j]:
            high = i - 1
        else:
            if i == 0:
                left_max = b[j - 1]
            elif j == 0:
                left_max = a[i - 1]
            else:
                left_max = max(a[i - 1], b[j - 1])

            if (m + n) % 2:
                return left_max

            if i == m:
                right_min = b[j]
            elif j == n:
                right_min = a[i]
            else:
                right_min = min(a[i], b[j])

            return (left_max + right_min) / 2
